# ! [doc = " Windows-specific extensions to general I/O primitives."] # ! [doc = ""] # ! [doc = " Just like raw pointers, raw Windows handles and sockets point to resources"] # ! [doc = " with dynamic lifetimes, and they can dangle if they outlive their resources"] # ! [doc = " or be forged if they're created from invalid values."] # ! [doc = ""] # ! [doc = " This module provides three types for representing raw handles and sockets"] # ! [doc = " with different ownership properties: raw, borrowed, and owned, which are"] # ! [doc = " analogous to types used for representing pointers. These types reflect concepts of [I/O"] # ! [doc = " safety][io-safety] on Windows."] # ! [doc = ""] # ! [doc = " | Type                   | Analogous to |"] # ! [doc = " | ---------------------- | ------------ |"] # ! [doc = " | [`RawHandle`]          | `*const _`   |"] # ! [doc = " | [`RawSocket`]          | `*const _`   |"] # ! [doc = " |                        |              |"] # ! [doc = " | [`BorrowedHandle<'a>`] | `&'a _`      |"] # ! [doc = " | [`BorrowedSocket<'a>`] | `&'a _`      |"] # ! [doc = " |                        |              |"] # ! [doc = " | [`OwnedHandle`]        | `Box<_>`     |"] # ! [doc = " | [`OwnedSocket`]        | `Box<_>`     |"] # ! [doc = ""] # ! [doc = " Like raw pointers, `RawHandle` and `RawSocket` values are primitive values."] # ! [doc = " And in new code, they should be considered unsafe to do I/O on (analogous"] # ! [doc = " to dereferencing them). Rust did not always provide this guidance, so"] # ! [doc = " existing code in the Rust ecosystem often doesn't mark `RawHandle` and"] # ! [doc = " `RawSocket` usage as unsafe."] # ! [doc = " Libraries are encouraged to migrate, either by adding `unsafe` to APIs"] # ! [doc = " that dereference `RawHandle` and `RawSocket` values, or by using to"] # ! [doc = " `BorrowedHandle`, `BorrowedSocket`, `OwnedHandle`, or `OwnedSocket`."] # ! [doc = ""] # ! [doc = " Like references, `BorrowedHandle` and `BorrowedSocket` values are tied to a"] # ! [doc = " lifetime, to ensure that they don't outlive the resource they point to."] # ! [doc = " These are safe to use. `BorrowedHandle` and `BorrowedSocket` values may be"] # ! [doc = " used in APIs which provide safe access to any system call except for"] # ! [doc = " `CloseHandle`, `closesocket`, or any other call that would end the"] # ! [doc = " dynamic lifetime of the resource without ending the lifetime of the"] # ! [doc = " handle or socket."] # ! [doc = ""] # ! [doc = " `BorrowedHandle` and `BorrowedSocket` values may be used in APIs which"] # ! [doc = " provide safe access to `DuplicateHandle` and `WSADuplicateSocketW` and"] # ! [doc = " related functions, so types implementing `AsHandle`, `AsSocket`,"] # ! [doc = " `From<OwnedHandle>`, or `From<OwnedSocket>` should not assume they always"] # ! [doc = " have exclusive access to the underlying object."] # ! [doc = ""] # ! [doc = " Like boxes, `OwnedHandle` and `OwnedSocket` values conceptually own the"] # ! [doc = " resource they point to, and free (close) it when they are dropped."] # ! [doc = ""] # ! [doc = " See the [`io` module docs][io-safety] for a general explanation of I/O safety."] # ! [doc = ""] # ! [doc = " [`BorrowedHandle<'a>`]: crate::os::windows::io::BorrowedHandle"] # ! [doc = " [`BorrowedSocket<'a>`]: crate::os::windows::io::BorrowedSocket"] # ! [doc = " [io-safety]: crate::io#io-safety"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; mod handle ; mod raw ; mod socket ; #[stable (feature = "io_safety" , since = "1.63.0")] pub use handle :: * ; #[stable (feature = "rust1" , since = "1.0.0")] pub use raw :: * ; #[stable (feature = "io_safety" , since = "1.63.0")] pub use socket :: * ; #[cfg (test)] mod tests ;